def editor_icon(name: str, color: str = "#d8dde3") -> QIcon:
    """Draw small dependency-free editor icons that stay crisp in dark UI."""
    pixmap = QPixmap(24, 24)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing)
    pen = QPen(QColor(color), 1.8)
    pen.setCapStyle(Qt.RoundCap)
    pen.setJoinStyle(Qt.RoundJoin)
    painter.setPen(pen)
    painter.setBrush(Qt.NoBrush)
    if name == "selection":
        painter.setBrush(QColor(color))
        painter.drawPolygon(QPolygon([QPoint(5, 3), QPoint(18, 13), QPoint(11, 14), QPoint(8, 21)]))
    elif name == "type":
        painter.drawLine(5, 5, 19, 5)
        painter.drawLine(12, 5, 12, 20)
        painter.drawLine(8, 20, 16, 20)
    elif name == "prompt":
        painter.drawRoundedRect(3, 4, 18, 14, 3, 3)
        painter.drawLine(8, 18, 6, 22)
        for x in (8, 12, 16):
            painter.drawPoint(x, 11)
    elif name == "hand":
        painter.drawLine(7, 12, 7, 7)
        painter.drawLine(10, 12, 10, 4)
        painter.drawLine(13, 12, 13, 3)
        painter.drawLine(16, 13, 16, 6)
        painter.drawLine(7, 11, 4, 10)
        painter.drawLine(4, 10, 4, 13)
        painter.drawLine(4, 13, 9, 20)
        painter.drawLine(9, 20, 17, 20)
        painter.drawLine(17, 20, 20, 13)
        painter.drawLine(20, 13, 20, 9)
        painter.drawLine(20, 9, 18, 8)
    elif name == "razor":
        painter.drawLine(4, 18, 18, 4)
        painter.drawLine(6, 20, 20, 6)
        painter.drawLine(4, 18, 9, 21)
        painter.drawLine(18, 4, 21, 9)
    elif name == "shot":
        painter.drawRect(3, 5, 18, 14)
        painter.drawLine(8, 5, 8, 19)
        painter.drawLine(16, 5, 16, 19)
        painter.drawLine(3, 10, 21, 10)
    elif name == "transition":
        painter.drawRect(3, 6, 10, 12)
        painter.drawRect(11, 6, 10, 12)
        painter.drawLine(9, 4, 15, 20)
    elif name == "marker":
        painter.setBrush(QColor(color))
        painter.drawPolygon(QPolygon([QPoint(6, 3), QPoint(18, 3), QPoint(18, 15), QPoint(12, 21), QPoint(6, 15)]))
    elif name == "track_add":
        painter.drawRect(3, 6, 18, 12)
        painter.drawLine(12, 8, 12, 16)
        painter.drawLine(8, 12, 16, 12)
    elif name == "track_delete":
        painter.drawRect(6, 8, 12, 12)
        painter.drawLine(5, 6, 19, 6)
        painter.drawLine(9, 3, 15, 3)
        painter.drawLine(10, 10, 10, 17)
        painter.drawLine(14, 10, 14, 17)
    elif name == "power":
        painter.drawArc(5, 5, 14, 14, 35 * 16, 290 * 16)
        painter.drawLine(12, 2, 12, 11)
    elif name == "lock":
        painter.drawRoundedRect(5, 10, 14, 11, 2, 2)
        painter.drawArc(8, 3, 8, 12, 0, 180 * 16)
    elif name == "eye":
        painter.drawEllipse(3, 7, 18, 11)
        painter.setBrush(QColor(color))
        painter.drawEllipse(10, 10, 4, 4)
    elif name == "settings":
        for y, x in ((6, 9), (12, 15), (18, 7)):
            painter.drawLine(3, y, 21, y)
            painter.setBrush(QColor(color))
            painter.drawEllipse(x - 2, y - 2, 4, 4)
            painter.setBrush(Qt.NoBrush)
    elif name == "mute":
        painter.drawLine(4, 10, 8, 10)
        painter.drawLine(8, 10, 13, 6)
        painter.drawLine(13, 6, 13, 18)
        painter.drawLine(13, 18, 8, 14)
        painter.drawLine(8, 14, 4, 14)
        painter.drawLine(16, 9, 21, 15)
        painter.drawLine(21, 9, 16, 15)
    elif name == "solo":
        painter.drawText(QRectF(2, 1, 20, 22), Qt.AlignCenter, "S")
    painter.end()
    return QIcon(pixmap)


class GenerationBusyOverlay(QWidget):
    """Lightweight animated overlay used while ComfyUI is executing."""

    def __init__(self, parent: QWidget) -> None:
        super().__init__(parent)
        self.angle = 0
        self.started_monotonic = 0.0
        self.completed_shots = 0
        self.total_shots = 0
        self.completed_weight_seconds = 0.0
        self.total_weight_seconds = 0.0
        self.active_shots: list[str] = []
        self.message = "ComfyUI running…"
        self.timer = QTimer(self)
        self.timer.setInterval(45)
        self.timer.timeout.connect(self._advance)
        self.setAttribute(Qt.WA_TransparentForMouseEvents)
        parent.installEventFilter(self)
        self.hide()

    def eventFilter(self, watched: QObject, event: QEvent) -> bool:
        if watched is self.parent() and event.type() == QEvent.Resize:
            self.setGeometry(self.parent().rect())
        return False

    def start(self, message: str = "ComfyUI running…") -> None:
        self.message = message
        self.started_monotonic = time.monotonic()
        self.completed_shots = 0
        self.total_shots = 0
        self.completed_weight_seconds = 0.0
        self.total_weight_seconds = 0.0
        self.active_shots = []
        self.setGeometry(self.parent().rect())
        self.angle = 0
        self.show()
        self.raise_()
        self.timer.start()
        self.update()

    def set_message(self, message: str) -> None:
        self.message = message
        self.update()

    def set_progress(
        self,
        *,
        completed_shots: int,
        total_shots: int,
        completed_weight_seconds: float,
        total_weight_seconds: float,
        active_shots: list[str] | None = None,
    ) -> None:
        self.completed_shots = max(0, int(completed_shots))
        self.total_shots = max(self.completed_shots, int(total_shots))
        self.total_weight_seconds = max(0.0, float(total_weight_seconds))
        self.completed_weight_seconds = min(
            self.total_weight_seconds,
            max(0.0, float(completed_weight_seconds)),
        )
        self.active_shots = [str(value) for value in (active_shots or []) if str(value)]
        self.update()

    def elapsed_seconds(self) -> float:
        if self.started_monotonic <= 0.0:
            return 0.0
        return max(0.0, time.monotonic() - self.started_monotonic)

    def weighted_percent(self) -> float:
        if self.total_weight_seconds <= 1e-9:
            return 0.0
        return min(
            100.0,
            max(0.0, self.completed_weight_seconds / self.total_weight_seconds * 100.0),
        )

    def stop(self) -> None:
        self.timer.stop()
        self.hide()

    def _advance(self) -> None:
        self.angle = (self.angle + 20) % 360
        self.update()

    def paintEvent(self, _event) -> None:  # noqa: N802
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing)
        # Keep the source/master visible during long renders. The compact dark
        # status card carries the spinner without replacing Program Monitor.
        painter.fillRect(self.rect(), QColor(5, 7, 9, 62))
        center = self.rect().center()
        card_width = min(max(300, self.width() // 2), max(300, self.width() - 36))
        card_height = 244 if self.total_shots else 190
        card = QRectF(
            center.x() - card_width / 2,
            center.y() - card_height / 2,
            card_width,
            card_height,
        )
        painter.setPen(QPen(QColor(83, 207, 223, 150), 1))
        painter.setBrush(QColor(8, 12, 16, 218))
        painter.drawRoundedRect(card, 10, 10)
        radius = 25
        spinner_center_y = card.top() + 48
        spinner_rect = QRectF(
            center.x() - radius,
            spinner_center_y - radius,
            radius * 2,
            radius * 2,
        )
        background_pen = QPen(QColor("#3d454d"), 6)
        background_pen.setCapStyle(Qt.RoundCap)
        painter.setPen(background_pen)
        painter.drawArc(spinner_rect, 0, 360 * 16)
        active_pen = QPen(QColor("#36bfd7"), 6)
        active_pen.setCapStyle(Qt.RoundCap)
        painter.setPen(active_pen)
        painter.drawArc(spinner_rect, -self.angle * 16, 105 * 16)
        elapsed = round(self.elapsed_seconds())
        hours, remainder = divmod(elapsed, 3600)
        minutes, seconds = divmod(remainder, 60)
        message_upper = self.message.upper()
        activity_label = (
            "ANALYSING"
            if "QWEN" in message_upper or "ANALYS" in message_upper
            else "GENERATING"
        )
        painter.setPen(QColor("#f1f5f7"))
        painter.drawText(
            QRectF(card.left() + 12, card.top() + 80, card.width() - 24, 22),
            Qt.AlignHCenter | Qt.AlignVCenter,
            f"{activity_label}  ·  ELAPSED {hours:02d}:{minutes:02d}:{seconds:02d}",
        )
        painter.drawText(
            QRectF(card.left() + 18, card.top() + 105, card.width() - 36, 42),
            Qt.AlignHCenter | Qt.AlignTop | Qt.TextWordWrap,
            self.message,
        )
        if self.total_shots:
            completed_percent = self.weighted_percent()
            remaining_percent = max(0.0, 100.0 - completed_percent)
            remaining_shots = max(0, self.total_shots - self.completed_shots)
            active = ", ".join(self.active_shots)
            active_text = f"  ·  Processing {active}" if active else ""
            painter.setPen(QColor("#b9c5cc"))
            painter.drawText(
                QRectF(card.left() + 18, card.top() + 150, card.width() - 36, 22),
                Qt.AlignHCenter | Qt.AlignVCenter,
                f"Shots {self.completed_shots}/{self.total_shots} completed  ·  "
                f"{remaining_shots} remaining{active_text}",
            )
            painter.drawText(
                QRectF(card.left() + 18, card.top() + 174, card.width() - 36, 22),
                Qt.AlignHCenter | Qt.AlignVCenter,
                f"Completed {completed_percent:.1f}%  ·  Remaining {remaining_percent:.1f}%",
            )
            bar = QRectF(card.left() + 26, card.top() + 207, card.width() - 52, 10)
            painter.setPen(Qt.NoPen)
            painter.setBrush(QColor("#303942"))
            painter.drawRoundedRect(bar, 5, 5)
            if completed_percent > 0.0:
                fill = QRectF(
                    bar.left(),
                    bar.top(),
                    bar.width() * completed_percent / 100.0,
                    bar.height(),
                )
                painter.setBrush(QColor("#36bfd7"))
                painter.drawRoundedRect(fill, 5, 5)


class JsonLineProcess(QObject):
    """Supervise one crash-isolated JSON worker with non-blocking queued input.

    Worker requests can contain large BLIP evidence, schemas and prompts.  A
    Windows anonymous pipe applies backpressure while the child is busy with
    an earlier inference, so writing/flushing that pipe from the Qt thread can
    freeze the whole Studio on the third consecutive request.  Only the
    dedicated writer thread below may touch worker stdin.
    """

    message = Signal(dict)
    finished = Signal(int, str)

    def __init__(self, parent: QObject | None = None, name: str = "worker") -> None:
        super().__init__(parent)
        self.name = name
        self.process: subprocess.Popen[str] | None = None
        self._thread: threading.Thread | None = None
        self._writer_thread: threading.Thread | None = None
        self._write_lock = threading.Lock()
        self._write_event = threading.Event()
        self._pending: list[dict] = []
        self._writer_error = ""
        self._ready = False
        self._stopping = False
        self.generation = 0
        self.started_monotonic = 0.0
        self.last_output_monotonic = 0.0

    def is_running(self) -> bool:
        return self.process is not None and self.process.poll() is None

    def is_ready(self) -> bool:
        return self.is_running() and self._ready

    def start(self, program: str, arguments: list[str]) -> bool:
        if self.process is not None:
            return self.is_running()
        self._ready = False
        self._stopping = False
        self._writer_error = ""
        self._write_event.clear()
        self.generation += 1
        self.started_monotonic = time.monotonic()
        self.last_output_monotonic = self.started_monotonic
        process = subprocess.Popen(
            [program, *arguments],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            bufsize=1,
            env={**os.environ, "PYTHONUTF8": "1", "PYTHONIOENCODING": "utf-8"},
            creationflags=(
                getattr(subprocess, "CREATE_NO_WINDOW", 0)
                | getattr(subprocess, "BELOW_NORMAL_PRIORITY_CLASS", 0)
            ),
        )
        self.process = process
        generation = self.generation
        self._writer_thread = threading.Thread(
            target=self._write_loop,
            args=(process, generation),
            name=f"{self.name}-writer-{generation}",
            daemon=True,
        )
        self._writer_thread.start()
        self._thread = threading.Thread(
            target=self._read_loop,
            args=(process, generation),
            name=f"{self.name}-reader-{generation}",
            daemon=True,
        )
        self._thread.start()
        return True

    def _read_loop(self, process: subprocess.Popen[str], generation: int) -> None:
        log: list[str] = []
        assert process.stdout is not None
        for raw in process.stdout:
            self.last_output_monotonic = time.monotonic()
            line = raw.strip()
            if not line:
                continue
            try:
                payload = json.loads(line)
                if payload.get("ready"):
                    with self._write_lock:
                        if self.process is process and generation == self.generation:
                            self._ready = True
                            self._write_event.set()
                self.message.emit(payload)
            except json.JSONDecodeError:
                log.append(line)
            except (BrokenPipeError, OSError) as exc:
                log.append(f"input queue failed: {exc}")
        exit_code = process.wait()
        try:
            process.stdout.close()
        except OSError:
            pass
        try:
            if process.stdin and not process.stdin.closed:
                process.stdin.close()
        except OSError:
            pass
        with self._write_lock:
            is_current = self.process is process and generation == self.generation
            if is_current:
                self.process = None
                self._ready = False
                self._write_event.set()
                if not self._stopping:
                    log.append(f"{self.name} exited with code {exit_code}")
                if self._writer_error:
                    log.append(self._writer_error)
        if log:
            try:
                CACHE_ROOT.mkdir(parents=True, exist_ok=True)
                with (CACHE_ROOT / "recognition_workers.log").open("a", encoding="utf-8") as handle:
                    handle.write(f"\n[{time.strftime('%Y-%m-%d %H:%M:%S')}] {self.name}\n")
                    handle.write("\n".join(log[-100:]) + "\n")
            except OSError:
                pass
        if is_current:
            self.finished.emit(exit_code, "\n".join(log[-30:]))

    def _write_loop(self, process: subprocess.Popen[str], generation: int) -> None:
        """Drain requests without ever blocking the GUI or stdout reader."""
        while True:
            self._write_event.wait()
            while True:
                with self._write_lock:
                    if (
                        self.process is not process
                        or generation != self.generation
                        or self._stopping
                    ):
                        return
                    if not self._ready or not self._pending:
                        # Clearing under the same lock used by write_json avoids
                        # losing a wake-up between the empty check and clear.
                        self._write_event.clear()
                        break
                    payload = self._pending.pop(0)
                try:
                    if process.stdin is None:
                        raise BrokenPipeError("worker stdin is unavailable")
                    process.stdin.write(json.dumps(payload, ensure_ascii=False) + "\n")
                    process.stdin.flush()
                except (BrokenPipeError, OSError) as exc:
                    with self._write_lock:
                        self._writer_error = (
                            f"input queue failed while writing in background: {exc}"
                        )
                        self._pending.clear()
                    try:
                        process.terminate()
                    except OSError:
                        pass
                    return

    def write_json(self, payload: dict) -> None:
        if not self.is_running() or self.process is None or self.process.stdin is None:
            raise RuntimeError("Background worker is not running")
        with self._write_lock:
            # Always enqueue.  Even a ready child may be busy processing its
            # previous line and unable to drain the OS pipe yet.
            self._pending.append(payload)
            self._write_event.set()

    def discard_pending(self) -> None:
        with self._write_lock:
            self._pending.clear()

    def terminate_now(self, reason: str = "") -> None:
        process = self.process
        if process is not None and process.poll() is None:
            if reason:
                with self._write_lock:
                    self._writer_error = str(reason).strip()
            try:
                process.terminate()
            except OSError:
                pass

    def stop(self) -> None:
        process = self.process
        if process is None:
            return
        self._stopping = True
        with self._write_lock:
            self._pending.clear()
            self._write_event.set()
        try:
            if process.stdin:
                process.stdin.close()
            process.wait(timeout=1.5)
        except subprocess.TimeoutExpired:
            process.terminate()
            try:
                process.wait(timeout=0.8)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=0.8)
        thread = self._thread
        if thread and thread is not threading.current_thread() and thread.is_alive():
            thread.join(timeout=0.5)
        writer = self._writer_thread
        if writer and writer is not threading.current_thread() and writer.is_alive():
            writer.join(timeout=0.5)


TIMELINE_STATE_FIELDS = (
    "timeline_placed",
    "timeline_lane",
    "start_seconds",
    "end_seconds",
    "activation_mode",
    "timeline_track_id",
    "playback_speed",
    "source_in_seconds",
    "source_out_seconds",
    "fade_in_seconds",
    "fade_out_seconds",
    "transition_in",
    "transition_out",
    "clip_prompt",
    "monitor_visible",
)


@dataclass(slots=True)
class TimelineTrack:
    track_id: str
    name: str
    kind: str
    color: str
    enabled: bool = True
    locked: bool = False
    height: int = 20
    visible: bool = True
    opacity: float = 1.0
    blend_mode: str = "Normal"
    muted: bool = False
    solo: bool = False
    volume: float = 1.0
    pan: float = 0.0

    def __post_init__(self) -> None:
        self.height = max(20, min(140, int(self.height)))
        self.opacity = max(0.0, min(1.0, float(self.opacity)))
        self.volume = max(0.0, min(1.0, float(self.volume)))
        self.pan = max(-1.0, min(1.0, float(self.pan)))


@dataclass(slots=True)
class TextLayer:
    layer_id: str
    text: str
    start_seconds: float
    end_seconds: float
    track_id: str
    font_size: int = 48
    color: str = "#ffffff"
    position_x: float = 0.5
    position_y: float = 0.5
    content_role: str = "on_screen_text"
    speaker: str = "S1"
    language: str = "English"
    delivery: str = "Natural"
    lip_sync: bool = True
    shot_id: str = ""
    speech_timing_auto_adjusted: bool = False
    overlap_policy: str = "auto"
    timeline_visible_text_kind: str = ""
    render_owner: str = "h3"
    voice_gender: str = "auto"

    def __post_init__(self) -> None:
        self.font_size = max(8, min(240, int(self.font_size)))
        self.start_seconds = max(0.0, float(self.start_seconds))
        self.end_seconds = max(self.start_seconds + 0.1, float(self.end_seconds))
        self.position_x = max(0.0, min(1.0, float(self.position_x)))
        self.position_y = max(0.0, min(1.0, float(self.position_y)))
        if self.content_role not in {"on_screen_text", "dialogue", "voice_over", "lyrics"}:
            self.content_role = "on_screen_text"
        normalized_speaker = str(self.speaker or "S1").strip().upper()
        self.speaker = (
            normalized_speaker
            if re.fullmatch(r"S[1-9]\d*", normalized_speaker)
            else "S1"
        )
        self.language = str(self.language).strip() or "English"
        if re.search(r"[\u3400-\u9fff]", self.text) and self.language.lower() in {
            "english", "original language", "auto", "chinese", "中文",
        }:
            self.language = "Mandarin Chinese"
        gender = str(self.voice_gender or "auto").strip().casefold()
        self.voice_gender = gender if gender in {"auto", "male", "female"} else "auto"
        self.delivery = str(self.delivery).strip() or "Natural"
        self.lip_sync = bool(self.lip_sync)
        self.speech_timing_auto_adjusted = bool(self.speech_timing_auto_adjusted)
        self.overlap_policy = normalize_speech_overlap_policy(self.overlap_policy)
        self.timeline_visible_text_kind = str(self.timeline_visible_text_kind or "")
        self.render_owner = (
            "studio_graphics"
            if str(self.render_owner).strip().casefold() == "studio_graphics"
            else "h3"
        )


def effective_native_speech_layer(
    layer: TextLayer,
    *,
    preserve_full_window: bool = False,
) -> TextLayer:
    """Return a prompt-only Text Layer with no unused native-vocal tail.

    Older projects and manually loaded Design JSON may contain a short line
    stretched across an entire camera Shot.  Do not mutate the editable
    Timeline clip while compiling those projects; instead make H3's native
    speech whitelist end at the conservative delivery budget.  Supplied TTS,
    MTV performance audio and Lyrics retain their authored/audio-owned range.
    """

    compiled = deepcopy(layer)
    if (
        preserve_full_window
        or compiled.content_role not in {"dialogue", "voice_over"}
        or not compiled.text.strip()
    ):
        return compiled
    budget = speech_timing_budget(
        compiled.text,
        compiled.language,
        compiled.delivery,
        compiled.end_seconds - compiled.start_seconds,
    )
    required = max(0.5, float(budget.get("required_seconds", 0.5) or 0.5))
    compiled.end_seconds = min(
        compiled.end_seconds,
        round(compiled.start_seconds + required, 6),
    )
    return compiled


def text_layer_from_mapping(value: dict) -> TextLayer:
    """Load current or future Text Layer JSON without rejecting extra metadata."""
    allowed = TextLayer.__dataclass_fields__.keys()
    return TextLayer(**{key: value[key] for key in allowed if key in value})


def text_layer_track_kind(content_role: str) -> str:
    """Map visible titles to V tracks and authored speech to A tracks."""
    return "visual" if content_role == "on_screen_text" else "audio"


def default_text_layer_track(content_role: str) -> str:
    return {
        "on_screen_text": "V4",
        "dialogue": "A4",
        "voice_over": "A5",
        "lyrics": "A6",
    }.get(content_role, "V4")


def text_layer_track_name(track_id: str, content_role: str) -> str:
    role_name = {
        "on_screen_text": "Type",
        "dialogue": "Dialogue",
        "voice_over": "Voice-over",
        "lyrics": "Lyrics",
    }.get(content_role, "Type")
    return f"{track_id} {role_name}"


@dataclass(slots=True)
class DirectorCue:
    cue_id: str
    cue_type: str
    start_seconds: float
    end_seconds: float
    preset: str
    detail: str = ""
    track_id: str = ""
    framing: str = "Medium-wide"
    camera_angle: str = "Eye level"
    camera_movement: str = "Static"
    movement_speed: str = "Slow"
    movement_amplitude: str = "Small"
    subject_action: str = ""
    environment_response: str = ""
    continuity_mode: str = "Auto"
    semantic_reference_directions: dict[str, str] = field(default_factory=dict)
    continuity_state: str = ""
    optional_flourish: str = ""
    h3_executable_action: str = ""
    h3_optional_flourish: str = ""
    action_budget_status: str = "within_budget"
    action_budget_notes: str = ""
    authored_subject_action: str = ""
    authored_environment_response: str = ""
    environment_interaction: str = ""
    incoming_environment_state: str = ""
    outgoing_environment_state: str = ""
    crowd_reaction: str = ""
    location_transition: str = ""
    environment_state_status: str = ""
    environment_physics_schema_version: int = 0
    combat_action_chain: str = ""
    incoming_combat_state: str = ""
    outgoing_combat_state: str = ""
    next_action_trigger: str = ""
    event_causality_chain: str = ""
    physical_feedback_chain: str = ""
    causal_risk_original_action: str = ""
    causal_risk_repair_status: str = ""
    causal_risk_repair_notes: str = ""
    causal_validation_status: str = ""
    causal_validation_issues: list[str] = field(default_factory=list)
    causal_validation_inherited_fields: list[str] = field(default_factory=list)
    final_action_resolution: str = ""
    final_camera_resolution: str = ""
    final_action_stable: bool = False
    combat_continuity_status: str = ""
    combat_continuity_notes: str = ""
    combat_action_schema_version: int = 0
    combat_fact_context: str = ""
    combat_story_duty_index: int = 0
    combat_story_duty: str = ""
    combat_story_duty_instruction: str = ""
    combat_action_beats: list[dict] = field(default_factory=list)
    combat_action_carrier: str = ""
    combat_force_vector: dict[str, str] = field(default_factory=dict)
    incoming_combat_state_vector: dict[str, str] = field(default_factory=dict)
    outgoing_combat_state_vector: dict[str, str] = field(default_factory=dict)
    camera_position_sector: str = ""
    camera_motion_relation: str = ""
    camera_action_trigger: str = ""
    dynamic_camera_direction: str = ""
    contact_material: str = ""
    environment_force_vector: dict[str, str] = field(default_factory=dict)
    combat_action_chain_user_edited: bool = False
    incoming_combat_state_user_edited: bool = False
    outgoing_combat_state_user_edited: bool = False
    next_action_trigger_user_edited: bool = False
    environment_interaction_user_edited: bool = False
    incoming_environment_state_user_edited: bool = False
    outgoing_environment_state_user_edited: bool = False
    crowd_reaction_user_edited: bool = False
    location_transition_user_edited: bool = False
    native_audio_direction: str = ""
    environment_continuity: str = ""
    audio_reference_intent: str = ""
    native_audio_qc_status: str = "Not analyzed"
    native_audio_direction_user_edited: bool = False
    environment_continuity_user_edited: bool = False
    audio_reference_intent_user_edited: bool = False
    native_audio_qc_user_edited: bool = False
    # Structured visual-speech controls owned by Shot Visual Editor.  These
    # fields take precedence over fragile prose-marker inference at compile
    # time, while remaining backward compatible with older projects.
    speech_visual_mode: str = "auto"
    mouth_behavior: str = ""
    voice_position: str = "auto"
    # Once the user changes any Shot Visual Editor speech/performance control,
    # the saved Shot becomes authoritative.  Automatic Source-Video speaker
    # routing must never overwrite that decision on save, reload or compile.
    speech_visual_controls_user_edited: bool = False
    # Shot-local lip-sync routing. ``auto`` preserves the existing Timeline /
    # Special Skill policy. ``enabled`` names one visible P identity and one
    # audible timing source; ``disabled`` keeps every visible mouth neutral
    # even while off-screen or non-diegetic audio continues.
    lip_sync_mode: str = "auto"
    lip_sync_target: str = ""
    lip_sync_source: str = "auto"
    # Explicit Shot-local cast substitutions authored by Shot Visual Editor.
    # The key is the original role Picture and the value is the selected
    # replacement Picture. Keeping this ledger prevents later prompt sync
    # from rediscovering a superseded face from stale prose.
    character_identity_overrides: dict[str, str] = field(default_factory=dict)
    # Source-Video Remake requires a second, role-addressed layer because two
    # distinct V1 people may intentionally share the same P Picture. This map
    # keeps Shot-local R1/R2 edits independent even when both currently use P4.
    source_role_identity_overrides: dict[str, str] = field(default_factory=dict)
    # Optional explicit subset selected by clicking people in the V1 Person
    # Picker. Empty preserves legacy behaviour: swap every visible mapped role.
    source_role_swap_selection: list[str] = field(default_factory=list)
    # Shot-local manual actor rectangles authored in the V1 Person Picker.
    # Coordinates are normalized to the displayed V1 frame and take
    # precedence over uncertain Qwen track boxes during Character Swap.
    source_role_bbox_overrides: dict[str, list[float]] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if self.cue_type not in DIRECTOR_LANE_TYPES and self.cue_type != "cut":
            self.cue_type = "marker"
        self.start_seconds = max(0.0, float(self.start_seconds))
        self.end_seconds = max(self.start_seconds + 0.05, float(self.end_seconds))
        if self.continuity_mode not in CONTINUITY_MODE_LABELS:
            self.continuity_mode = "Auto"
        if self.speech_visual_mode not in {
            "auto", "on_screen_speaker", "silent_listener", "no_human_voice"
        }:
            self.speech_visual_mode = "auto"
        if self.voice_position not in {
            "auto", "on_screen", "offscreen", "behind_camera", "non_diegetic"
        }:
            self.voice_position = "auto"
        self.speech_visual_controls_user_edited = bool(
            self.speech_visual_controls_user_edited
        )
        if self.lip_sync_mode not in {"auto", "enabled", "disabled"}:
            self.lip_sync_mode = "auto"
        self.lip_sync_target = normalize_picture_reference(self.lip_sync_target)
        raw_lip_source = str(self.lip_sync_source or "auto").strip()
        if raw_lip_source.casefold() in {"auto", "text_layers"}:
            self.lip_sync_source = raw_lip_source.casefold()
        elif re.fullmatch(r"[AV][1-9]\d*", raw_lip_source, flags=re.I):
            self.lip_sync_source = raw_lip_source.upper()
        else:
            self.lip_sync_source = "auto"
        if not isinstance(self.character_identity_overrides, dict):
            self.character_identity_overrides = {}
        else:
            self.character_identity_overrides = {
                source: target
                for raw_source, raw_target in self.character_identity_overrides.items()
                if (source := normalize_picture_reference(raw_source))
                and (target := normalize_picture_reference(raw_target))
                and source != target
            }
        if not isinstance(self.source_role_identity_overrides, dict):
            self.source_role_identity_overrides = {}
        else:
            self.source_role_identity_overrides = {
                role: target
                for raw_role, raw_target in self.source_role_identity_overrides.items()
                if (role := str(raw_role or "").strip().upper())
                and re.fullmatch(r"R[1-9]\d*", role)
                and (
                    target := (
                        KEEP_V1_TARGET
                        if str(raw_target or "").strip().upper() == KEEP_V1_TARGET else
                        normalize_picture_reference(raw_target)
                    )
                )
            }
        if not isinstance(self.source_role_swap_selection, list):
            self.source_role_swap_selection = []
        else:
            self.source_role_swap_selection = list(dict.fromkeys(
                role for raw_role in self.source_role_swap_selection
                if (role := str(raw_role or "").strip().upper())
                and re.fullmatch(r"R[1-9]\d*", role)
            ))
        if not isinstance(self.source_role_bbox_overrides, dict):
            self.source_role_bbox_overrides = {}
        else:
            normalized_boxes: dict[str, list[float]] = {}
            for raw_role, raw_bbox in self.source_role_bbox_overrides.items():
                role = str(raw_role or "").strip().upper()
                if not re.fullmatch(r"R[1-9]\d*", role):
                    continue
                try:
                    left, top, right, bottom = [
                        float(value) for value in raw_bbox[:4]
                    ]
                except (TypeError, ValueError, OverflowError):
                    continue
                left, top = max(0.0, left), max(0.0, top)
                right, bottom = min(1.0, right), min(1.0, bottom)
                if right - left < 0.02 or bottom - top < 0.02:
                    continue
                normalized_boxes[role] = [left, top, right, bottom]
            self.source_role_bbox_overrides = normalized_boxes
        if not isinstance(self.semantic_reference_directions, dict):
            self.semantic_reference_directions = {}
        else:
            self.semantic_reference_directions = {
                str(node_id): str(direction).strip()
                for node_id, direction in self.semantic_reference_directions.items()
                if str(node_id).strip() and str(direction).strip()
            }
        if self.cue_type == "shot" and not self.h3_executable_action:
            self.authored_subject_action = self.authored_subject_action or self.subject_action
            self.authored_environment_response = (
                self.authored_environment_response or self.environment_response
            )
            budgeted = normalize_shot_action_budget({
                "start_seconds": self.start_seconds,
                "end_seconds": self.end_seconds,
                "subject_action": self.authored_subject_action,
                "environment_response": self.authored_environment_response,
                "continuity_state": self.continuity_state,
                "optional_flourish": self.optional_flourish,
            })
            self.subject_action = budgeted["subject_action"]
            self.environment_response = budgeted["environment_response"]
            self.continuity_state = budgeted["continuity_state"]
            self.optional_flourish = budgeted["optional_flourish"]
            self.h3_executable_action = budgeted["h3_executable_action"]
            self.h3_optional_flourish = budgeted["h3_optional_flourish"]
            self.action_budget_status = budgeted["action_budget"]["status"]
            self.action_budget_notes = budgeted["action_budget"]["notes"]
        elif self.cue_type == "shot":
            self.authored_subject_action = self.authored_subject_action or self.subject_action
            self.authored_environment_response = (
                self.authored_environment_response or self.environment_response
            )


