    @staticmethod
    def _card_title(text: str) -> QLabel:
        label = QLabel(text)
        label.setObjectName("cardTitle")
        return label

    def _field_card(
        self,
        title: str,
        value_widget: QWidget,
        hint: str = "",
        callback=None,
        button_text: str = "",
    ) -> QFrame:
        card = QFrame()
        card.setObjectName("shotFieldCard")
        card.setMinimumHeight(86)
        layout = QVBoxLayout(card)
        layout.setContentsMargins(14, 10, 12, 10)
        header = QHBoxLayout()
        header.addWidget(self._card_title(title))
        header.addStretch(1)
        if hint:
            hint_label = QLabel(hint)
            hint_label.setObjectName("cardHint")
            header.addWidget(hint_label)
        layout.addLayout(header)
        value_row = QHBoxLayout()
        value_row.addWidget(value_widget, 1)
        if callback and button_text:
            button = QPushButton(button_text)
            button.setObjectName("cardEditButton")
            button.clicked.connect(callback)
            value_row.addWidget(button)
        layout.addLayout(value_row)
        return card

    @staticmethod
    def _character_source_references(cue: DirectorCue) -> list[str]:
        text = " ".join((
            cue.authored_subject_action or cue.subject_action,
            cue.detail,
            " ".join(str(key) for key in (cue.semantic_reference_directions or {}).keys()),
        ))
        refs = {
            normalize_picture_reference(match.group(1))
            for match in re.finditer(
                r"(?<![A-Za-z0-9_])@?(P[1-9]\d*)(?!\d)", text, flags=re.I
            )
        }
        refs.update(
            normalize_picture_reference(value)
            for value in (cue.character_identity_overrides or {}).keys()
        )
        if cue.lip_sync_target:
            refs.add(normalize_picture_reference(cue.lip_sync_target))
        return sorted(value for value in refs if value)

    @classmethod
    def _character_label(cls, cue: DirectorCue) -> str:
        overrides = cue.character_identity_overrides or {}
        refs = [overrides.get(source, source) for source in cls._character_source_references(cue)]
        refs = list(dict.fromkeys(refs))
        return " · ".join(f"@{ref}" for ref in refs[:4]) or "Scene subject"

    @staticmethod
    def _picture_identity_choices(parent: QWidget | None) -> list[dict]:
        scan = getattr(parent, "scan", None)
        if scan is None:
            return []
        preview_paths = getattr(parent, "preview_paths", {}) or {}
        choices: dict[str, dict] = {}
        for asset in scan.assets:
            media_id = normalize_picture_reference(stable_reference_id(asset))
            if not media_id or asset.media_type != "image" or media_id in choices:
                continue
            icon = QIcon()
            candidates = [
                preview_paths.get(str(asset.clip_id or "")),
                preview_paths.get(str(asset.node_id or "")),
                preview_paths.get(str(asset.source_node_id or "")),
                asset.local_path,
            ]
            for candidate in candidates:
                if candidate and Path(str(candidate)).is_file():
                    pixmap = QPixmap(str(candidate))
                    if not pixmap.isNull():
                        icon = QIcon(pixmap)
                        break
            source_face = "[V1_SOURCE_FACE:" in str(asset.clip_prompt or "")
            # Legacy builds materialized KEEP V1 as a synthetic P Picture.
            # Do not expose those files as replacement identities: KEEP V1 is
            # now a first-class no-generation choice in the role row.
            if source_face:
                continue
            choices[media_id] = {
                "media_id": media_id,
                "icon": icon,
                "label": f"@{media_id}",
                "direction": " ".join(filter(None, (
                    str(asset.clip_prompt or "").strip(),
                    str(asset.recognition or "").strip(),
                )))[:1200],
            }
        return [choices[key] for key in sorted(
            choices, key=lambda value: int(re.search(r"\d+", value).group())
        )]

    @staticmethod
    def _available_lip_sync_audio_choices(
        parent: QWidget | None,
        cue: DirectorCue,
    ) -> list[tuple[str, str]]:
        """List only audible references that are active across this Shot."""

        choices: list[tuple[str, str]] = [
            ("Auto · current Timeline / Special Skill rule", "auto"),
            ("Authored Dialogue or Lyrics Text Layer", "text_layers"),
        ]
        scan = getattr(parent, "scan", None)
        if scan is None:
            return choices
        seen: set[str] = set()
        for asset in scan.timeline_assets():
            media_id = stable_reference_id(asset).strip().upper()
            if (
                asset.media_type not in {"audio", "video"}
                or not re.fullmatch(r"[AV][1-9]\d*", media_id)
                or media_id in seen
                or not asset.timeline_placed
                or asset.activation_mode == "bypass"
                or not ranges_intersect(
                    asset.start_seconds,
                    asset.end_seconds,
                    cue.start_seconds,
                    cue.end_seconds,
                )
            ):
                continue
            seen.add(media_id)
            kind = "audio timing" if asset.media_type == "audio" else "source-video audio"
            choices.append((f"@{media_id} · {kind}", media_id))
        return choices

    def _shot_reference_label(self, cue: DirectorCue, assets: list[MediaAsset]) -> str:
        refs = sorted({
            f"@{media_shortcut(asset)}" for asset in assets
            if media_shortcut(asset) and media_shortcut(asset).upper().startswith("P")
        })
        if refs:
            return "–".join(refs[:3])
        value = self._character_label(cue)
        return value if value != "Scene subject" else ""

    def _shot_preview(self, cue: DirectorCue, parent: QWidget | None) -> tuple[QPixmap, str]:
        canvas = QPixmap(428, 164)
        canvas.fill(QColor("#101820"))
        scan = getattr(parent, "scan", None)
        assets = []
        if scan is not None:
            assets = [
                asset for asset in scan.timeline_assets()
                if asset.timeline_placed
                and asset.media_type in {"image", "video"}
                and ranges_intersect(
                    asset.start_seconds, asset.end_seconds,
                    cue.start_seconds, cue.end_seconds,
                )
            ]
        preferred = {
            str(key).strip().upper() for key in (cue.semantic_reference_directions or {}).keys()
        }
        assets.sort(key=lambda asset: (
            0 if str(asset.node_id).upper() in preferred
            or media_shortcut(asset).upper() in preferred else 1,
            abs(float(asset.start_seconds) - cue.start_seconds),
        ))
        preview_paths = getattr(parent, "preview_paths", {}) or {}
        image_suffixes = {".png", ".jpg", ".jpeg", ".webp", ".bmp"}
        for asset in assets:
            candidates = [
                preview_paths.get(str(asset.clip_id or "")),
                preview_paths.get(str(asset.node_id or "")),
                preview_paths.get(str(asset.source_node_id or "")),
            ]
            local = Path(str(asset.local_path or ""))
            if local.suffix.lower() in image_suffixes:
                candidates.append(local)
            for candidate in candidates:
                if candidate and Path(candidate).is_file():
                    pixmap = QPixmap(str(candidate))
                    if not pixmap.isNull():
                        return pixmap, self._shot_reference_label(cue, assets)
        painter = QPainter(canvas)
        painter.setRenderHint(QPainter.Antialiasing)
        painter.fillRect(canvas.rect(), QColor("#0b131a"))
        painter.setPen(QColor("#263746"))
        for x in range(-120, canvas.width(), 70):
            painter.drawLine(x, canvas.height(), x + 150, 0)
        painter.setPen(QColor("#7f96a8"))
        painter.drawText(canvas.rect(), Qt.AlignCenter, f"{cue.cue_id}\nVISUAL REFERENCE")
        painter.end()
        return canvas, self._shot_reference_label(cue, assets)

    def _populate_shot_strip(self, parent: QWidget | None) -> None:
        all_shots = sorted(
            [row for row in getattr(parent, "director_cues", []) if row.cue_type == "shot"],
            key=lambda row: (row.start_seconds, row.end_seconds),
        )
        if not all_shots:
            all_shots = [self.cue]
        try:
            current = next(index for index, row in enumerate(all_shots) if row is self.cue)
        except StopIteration:
            current = next(
                (index for index, row in enumerate(all_shots) if row.cue_id == self.cue.cue_id), 0
            )
        start = max(0, min(current - 2, max(0, len(all_shots) - 5)))
        for shot in all_shots[start:start + 5]:
            pixmap, ref = self._shot_preview(shot, parent)
            card = ShotStripCard(shot, pixmap, ref, shot.cue_id == self.cue.cue_id)
            card.clicked.connect(self._navigate_to_shot)
            self.shot_strip_layout.addWidget(card)

    def _navigate_to_shot(self, cue_id: str) -> None:
        if cue_id == self.cue.cue_id:
            return
        self.pending_navigation_cue_id = cue_id
        self.accept()

    def _camera_summary(self) -> str:
        return " · ".join(filter(None, (
            self.framing_combo.currentText(),
            self.angle_combo.currentText(),
            self.movement_combo.currentText(),
        )))

    def _refresh_card_values(self) -> None:
        character_label = (
            " · ".join(
                f"{role}=@{picture}"
                for role, picture in self._source_role_bindings.items()
            )
            if self._source_role_bindings else self._character_label(self.cue)
        )
        if self._identity_change_payloads:
            character_label = " · ".join(
                f"{change.get('source_role_id') or '@' + str(change.get('source_reference', ''))} → "
                f"@{change.get('target_reference', '')}"
                for change in self._identity_change_payloads
            )
        if self._source_remake_editor and self._source_role_swap_selection:
            character_label = (
                character_label
                + "  ·  SWAP ONLY "
                + ", ".join(self._source_role_swap_selection)
            )
        self.shot_meta_label.setText(
            f"{self.cue.start_seconds:.3f}–{self.cue.end_seconds:.3f}s  ·  "
            f"{character_label} at {self.preset_edit.text().strip() or 'scene'}"
        )
        self.character_value.setText(character_label)
        if self.character_lock_hint is not None:
            self.character_lock_hint.setText(
                (
                    f"{len(self._identity_change_payloads)} identity change(s) staged"
                    if self._identity_change_payloads else "Identity locked"
                )
            )
        if self.character_unlock_button is not None:
            self.character_unlock_button.setText(
                "Change all" if self._identity_change_payloads else "Unlock"
            )
        self.camera_value.setText(self._camera_summary())
        mode = str(self.speech_mode_combo.currentData())
        for value, button in self.speech_buttons.items():
            button.setChecked(value == mode)
        self.speaking_hint.setText(
            self.speech_mode_combo.currentText()
            if mode == "auto" else f"{self.voice_position_combo.currentText()} voice"
        )
        self.mouth_value.setText(
            self.mouth_edit.text().strip() or (
                "Closed · no articulation" if mode in {"silent_listener", "no_human_voice"}
                else "Natural authored performance"
            )
        )
        self.voice_value.setText(self.voice_position_combo.currentText())
        lip_mode = str(self.lip_sync_mode_combo.currentData())
        lip_target = normalize_picture_reference(
            self.lip_sync_target_combo.currentData()
        )
        lip_source = str(self.lip_sync_source_combo.currentData() or "auto")
        if lip_mode == "disabled":
            lip_summary = "Off · all visible mouths remain neutral"
        elif lip_mode == "enabled":
            target_label = f"@{lip_target}" if lip_target else "Auto character"
            source_label = (
                "authored Text Layer"
                if lip_source == "text_layers"
                else f"@{lip_source}"
                if re.fullmatch(r"[AV]\d+", lip_source)
                else "automatic active audio"
            )
            lip_summary = f"On · {target_label} follows {source_label}"
        else:
            lip_summary = "Auto · Timeline / Special Skill decides"
        self.lip_sync_value.setText(lip_summary)
        self.action_value.setText(
            self.action_edit.toPlainText().strip() or "No authored visible action"
        )
        self.environment_value.setText(
            self.environment_edit.toPlainText().strip() or "Preserve established environment"
        )

    def _push_history(self) -> None:
        self._history.append(self._raw_ui_state())
        self._history = self._history[-30:]
        self.undo_button.setEnabled(True)
        self.saved_badge.setText("Edited")

    def _raw_ui_state(self) -> dict:
        return {
            "preset": self.preset_edit.text(),
            "framing": self.framing_combo.currentText(),
            "camera_angle": self.angle_combo.currentText(),
            "camera_movement": self.movement_combo.currentText(),
            "movement_speed": self.speed_combo.currentText(),
            "movement_amplitude": self.amplitude_combo.currentText(),
            "speech_visual_mode": str(self.speech_mode_combo.currentData()),
            "mouth_behavior": self.mouth_edit.text(),
            "voice_position": str(self.voice_position_combo.currentData()),
            "lip_sync_mode": str(self.lip_sync_mode_combo.currentData()),
            "lip_sync_target": normalize_picture_reference(
                self.lip_sync_target_combo.currentData()
            ),
            "lip_sync_source": str(
                self.lip_sync_source_combo.currentData() or "auto"
            ),
            "subject_action": self.action_edit.toPlainText(),
            "environment_response": self.environment_edit.toPlainText(),
            "detail": self.detail_edit.toPlainText(),
            "continuity_state": self.continuity_edit.toPlainText(),
            "native_audio_direction": self.native_audio_edit.toPlainText(),
            "identity_change_payloads": deepcopy(self._identity_change_payloads),
            "source_role_swap_selection": list(self._source_role_swap_selection),
            "source_role_bbox_overrides": deepcopy(
                self._source_role_bbox_overrides
            ),
        }

    def _load_raw_ui_state(self, value: dict) -> None:
        self.preset_edit.setText(str(value.get("preset", self.cue.preset)))
        self.framing_combo.setCurrentText(str(value.get("framing", self.cue.framing)))
        self.angle_combo.setCurrentText(str(value.get("camera_angle", self.cue.camera_angle)))
        self.movement_combo.setCurrentText(str(value.get("camera_movement", self.cue.camera_movement)))
        self.speed_combo.setCurrentText(str(value.get("movement_speed", self.cue.movement_speed)))
        self.amplitude_combo.setCurrentText(str(value.get("movement_amplitude", self.cue.movement_amplitude)))
        index = self.speech_mode_combo.findData(value.get("speech_visual_mode", "auto"))
        self.speech_mode_combo.setCurrentIndex(max(0, index))
        self.mouth_edit.setText(str(value.get("mouth_behavior", "")))
        index = self.voice_position_combo.findData(value.get("voice_position", "auto"))
        self.voice_position_combo.setCurrentIndex(max(0, index))
        index = self.lip_sync_mode_combo.findData(value.get("lip_sync_mode", "auto"))
        self.lip_sync_mode_combo.setCurrentIndex(max(0, index))
        target = normalize_picture_reference(value.get("lip_sync_target", ""))
        if target and self.lip_sync_target_combo.findData(target) < 0:
            self.lip_sync_target_combo.addItem(f"@{target}", target)
        index = self.lip_sync_target_combo.findData(target)
        self.lip_sync_target_combo.setCurrentIndex(max(0, index))
        source = str(value.get("lip_sync_source", "auto") or "auto")
        if self.lip_sync_source_combo.findData(source) < 0:
            self.lip_sync_source_combo.addItem(f"@{source} · saved source", source)
        index = self.lip_sync_source_combo.findData(source)
        self.lip_sync_source_combo.setCurrentIndex(max(0, index))
        self.action_edit.setPlainText(str(value.get("subject_action", "")))
        self.environment_edit.setPlainText(str(value.get("environment_response", "")))
        self.detail_edit.setPlainText(str(value.get("detail", "")))
        self.continuity_edit.setPlainText(str(value.get("continuity_state", "")))
        self.native_audio_edit.setPlainText(str(value.get("native_audio_direction", "")))
        payloads = value.get("identity_change_payloads")
        if isinstance(payloads, list):
            self._identity_change_payloads = [
                deepcopy(item) for item in payloads if isinstance(item, dict)
            ]
        else:
            # Recover the single-character draft format used by the first
            # Character Unlock implementation.
            legacy = value.get("identity_change_payload")
            self._identity_change_payloads = [deepcopy(legacy)] if isinstance(legacy, dict) else []
        swap_selection = value.get("source_role_swap_selection")
        if isinstance(swap_selection, list):
            self._source_role_swap_selection = list(dict.fromkeys(
                str(role).strip().upper()
                for role in swap_selection
                if re.fullmatch(r"R[1-9]\d*", str(role).strip(), flags=re.I)
            ))
        bbox_overrides = value.get("source_role_bbox_overrides")
        if isinstance(bbox_overrides, dict):
            self._source_role_bbox_overrides = deepcopy(bbox_overrides)
        self._refresh_card_values()

    def _undo_local(self) -> None:
        if not self._history:
            return
        self._load_raw_ui_state(self._history.pop())
        self.undo_button.setEnabled(bool(self._history))
        self.saved_badge.setText("Edited" if self._history else "Ready")

    def _restore_original(self) -> None:
        self._push_history()
        original = deepcopy(self._original_state)
        original["subject_action"] = (
            original.get("authored_subject_action") or original.get("subject_action", "")
        )
        original["environment_response"] = (
            original.get("authored_environment_response")
            or original.get("environment_response", "")
        )
        self._load_raw_ui_state(original)

    def _choose_speech(self, mode: str) -> None:
        if mode == str(self.speech_mode_combo.currentData()):
            return
        self._push_history()
        index = self.speech_mode_combo.findData(mode)
        self.speech_mode_combo.setCurrentIndex(max(0, index))
        if mode in {"silent_listener", "no_human_voice"}:
            self.lip_sync_mode_combo.setCurrentIndex(
                max(0, self.lip_sync_mode_combo.findData("disabled"))
            )
            self.lip_sync_target_combo.setCurrentIndex(0)
            if self.lip_sync_source_combo.findData("V1") >= 0:
                self.lip_sync_source_combo.setCurrentIndex(
                    self.lip_sync_source_combo.findData("V1")
                )
            if not self.mouth_edit.text().strip():
                self.mouth_edit.setText(
                    "lips naturally together; jaw still; blink and breathe only; "
                    "never follow the audible voice"
                )
        elif mode == "on_screen_speaker":
            self.lip_sync_mode_combo.setCurrentIndex(
                max(0, self.lip_sync_mode_combo.findData("enabled"))
            )
            if self.lip_sync_source_combo.findData("V1") >= 0:
                self.lip_sync_source_combo.setCurrentIndex(
                    self.lip_sync_source_combo.findData("V1")
                )
            if not normalize_picture_reference(self.lip_sync_target_combo.currentData()):
                visible = self._character_source_references(self.cue)
                if visible and self.lip_sync_target_combo.findData(visible[0]) >= 0:
                    self.lip_sync_target_combo.setCurrentIndex(
                        self.lip_sync_target_combo.findData(visible[0])
                    )
        self._refresh_card_values()

    def _edit_identity(self) -> None:
        overrides = self.cue.character_identity_overrides or {}
        source_role_bindings = dict(self._source_role_bindings)
        if self._source_remake_editor:
            fallback_target = normalize_picture_reference(
                self._identity_choices[0].get("media_id")
                if self._identity_choices else ""
            )
            # A freshly detected person is a real CURRENT ROLE even before the
            # user assigns a P Picture.  Previously this dialog rebuilt its
            # rows only from the persistent binding ledger, so an unbound Qwen
            # result could have a valid frame/box yet remain invisible.
            # The same rule also recovers Shot-local boxes from a saved Project
            # whose older global ledger no longer contains that R role.
            detected_role_ids = {
                *self._detected_unbound_source_roles,
                *self._source_role_visuals,
            }
            for raw_role in detected_role_ids:
                role = str(raw_role or "").strip().upper()
                if not re.fullmatch(r"R[1-9]\d*", role):
                    continue
                payload = self._detected_unbound_source_roles.get(role) or {}
                if role not in source_role_bindings:
                    payload = self._detected_unbound_source_roles.setdefault(
                        role,
                        {
                            "target_media_id": fallback_target,
                            "scene_index": int(
                                (self._source_role_visuals.get(role) or {}).get(
                                    "scene_index", 0
                                ) or 0
                            ),
                            "activate_source_role": bool(
                                (self._source_role_visuals.get(role) or {}).get(
                                    "activate_source_role", True
                                )
                            ),
                        },
                    )
                target = normalize_picture_reference(
                    (payload or {}).get("target_media_id")
                ) or fallback_target
                source_role_bindings.setdefault(role, target)
        identity_sources = (
            [
                (role, picture, True)
                for role, picture in source_role_bindings.items()
            ]
            if source_role_bindings else
            [
                (source, overrides.get(source, source), False)
                for source in self._character_source_references(self.cue)
            ]
        )
        if not identity_sources and not self._source_remake_editor:
            QMessageBox.information(
                self,
                "Character identity",
                "This Shot has no structured @P identity to replace.",
            )
            return
        if not self._identity_choices and not self._source_remake_editor:
            QMessageBox.information(
                self,
                "Character identity",
                "Load at least one P Picture in Media Pool before unlocking this Shot.",
            )
            return

        dialog = QDialog(self)
        dialog.setWindowTitle(f"Unlock All Characters · {self.cue.cue_id}")
        dialog.setMinimumWidth(700)
        layout = QVBoxLayout(dialog)
        warning = QLabel(
            "Identity changes are safe only when they use an existing Media Pool P Picture. "
            "The selected scope will be updated as one undoable transaction."
        )
        warning.setWordWrap(True)
        warning.setStyleSheet("color:#e5bd69; padding:6px;")
        layout.addWidget(warning)
        if self._source_remake_editor:
            detect_row = QHBoxLayout()
            detect_button = QPushButton("DETECT V1 PEOPLE")
            detect_button.setObjectName("shotDetectV1People")
            detect_button.setToolTip(
                "Decode every 24fps V1 relay frame in this Shot, let Qwen inspect the "
                "complete frame sequence, then add every visible source role that is not "
                "yet mapped to a P Picture."
            )
            detect_status = QLabel(
                "Qwen frame-by-frame scan · finds brief and multi-person appearances."
            )
            detect_status.setObjectName("shotEditorSubtitle")
            detect_row.addWidget(detect_button)
            detect_row.addWidget(detect_status, 1)
            layout.addLayout(detect_row)

            def apply_detected_people(detected: dict, error: str = "") -> None:
                if error:
                    QMessageBox.warning(
                        self,
                        "Detect V1 people failed",
                        error,
                    )
                    return
                missing = {
                    role: payload for role, payload in detected.items()
                    if role not in self._source_role_bindings
                }
                self._detected_unbound_source_roles.update(deepcopy(missing))
                fallback_target = normalize_picture_reference(
                    self._identity_choices[0].get("media_id")
                    if self._identity_choices else ""
                )
                self._source_role_bindings.update({
                    role: (
                        normalize_picture_reference(payload.get("target_media_id"))
                        or fallback_target
                    )
                    for role, payload in missing.items()
                    if (
                        normalize_picture_reference(payload.get("target_media_id"))
                        or fallback_target
                    )
                })
                # An empty selection means "all roles".  When this Shot was
                # already narrowed to an explicit subset, however, a freshly
                # detected person used to be rendered unchecked and therefore
                # disappeared again when Regenerate Dirty built the Relay
                # passes.  A Detect action is an explicit request to make the
                # newly discovered V1 source people available for replacement,
                # so add them to that subset without locking the user out of
                # unchecking them in the reopened dialog.
                if missing and self._source_role_swap_selection:
                    self._source_role_swap_selection = list(dict.fromkeys([
                        *self._source_role_swap_selection,
                        *(str(role).strip().upper() for role in missing),
                    ]))
                visual_resolver = getattr(
                    self.parentWidget(), "_source_role_visuals_for_shot", None
                )
                if callable(visual_resolver):
                    self._source_role_visuals = dict(visual_resolver(self.cue))
                picker_resolver = getattr(
                    self.parentWidget(), "_source_role_picker_for_shot", None
                )
                if callable(picker_resolver):
                    self._source_role_picker_payload = dict(picker_resolver(self.cue))
                if not missing:
                    QMessageBox.information(
                        self,
                        "Detect V1 people",
                        "The existing V1 roles were refreshed with frame-by-frame position "
                        "tracks. Click a person in the V1 frame to choose the swap target.",
                    )
                self._edit_identity()

            def detect_v1_people() -> None:
                starter = getattr(
                    self.parentWidget(), "_start_qwen_source_role_scan", None
                )
                if not callable(starter):
                    QMessageBox.warning(
                        self,
                        "Detect V1 people",
                        "The Qwen Shot scanner is not available.",
                    )
                    return
                if starter(self.cue, apply_detected_people):
                    dialog.reject()

            detect_button.clicked.connect(detect_v1_people)
        staged_by_source = {
            (
                str(item.get("source_role_id", "")).strip().upper()
                or normalize_picture_reference(item.get("source_reference"))
            ): item
            for item in self._identity_change_payloads
            if (
                str(item.get("source_role_id", "")).strip()
                or normalize_picture_reference(item.get("source_reference"))
            )
        }
        source_role_ids = [
            str(source).strip().upper()
            for source, _baseline, is_source_role in identity_sources
            if is_source_role
        ]
        keep_role_ids = {
            role for role, picture in source_role_bindings.items()
            if picture == KEEP_V1_TARGET
        }
        selected_roles = set(
            self._source_role_swap_selection or source_role_ids
        ) - keep_role_ids
        picker = None
        frame_label = None
        picker_payload = self._source_role_picker_payload
        picker_pixmap = picker_payload.get("pixmap", QPixmap())
        picker_roles = picker_payload.get("roles") or {}
        picker_role_views = picker_payload.get("role_views") or {}
        if (
            self._source_remake_editor
            and isinstance(picker_pixmap, QPixmap)
            and not picker_pixmap.isNull()
            and isinstance(picker_roles, dict)
            and (picker_roles or picker_role_views)
        ):
            picker_box = QGroupBox("SELECT THE PERSON TO REPLACE IN THIS V1 SHOT")
            picker_layout = QVBoxLayout(picker_box)
            picker = V1PersonPickerWidget(picker_pixmap, picker_roles, picker_box)
            picker.setMaximumHeight(390)
            picker.set_selected_roles(selected_roles)
            picker_layout.addWidget(picker)
            picker_hint = QLabel(
                "Click = replace only this boxed person · Ctrl+click = add/remove another "
                "person · drag a box to move it · drag an edge/corner to resize · focus a "
                "Current Role then Ctrl+click or Ctrl+drag empty space to add its box · "
                "repeated clicks cycle overlapping R roles."
            )
            picker_hint.setWordWrap(True)
            picker_hint.setStyleSheet("color:#69dce8; padding:3px;")
            picker_layout.addWidget(picker_hint)
            frame_label = QLabel(
                f"V1 frame {int(picker_payload.get('frame_index', 0) or 0)} · "
                f"{float(picker_payload.get('time_seconds', 0.0) or 0.0):.3f}s"
            )
            frame_label.setObjectName("v1PersonPickerFrameLabel")
            frame_label.setStyleSheet("color:#8da5b6;")
            picker_layout.addWidget(frame_label)
            layout.addWidget(picker_box)
        role_scroll = QScrollArea()
        role_scroll.setObjectName("shotIdentityRoleScroll")
        role_scroll.setWidgetResizable(True)
        role_scroll.setFrameShape(QFrame.NoFrame)
        role_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        role_scroll.setMinimumHeight(220)
        role_scroll_content = QWidget()
        role_scroll_content.setObjectName("shotIdentityRoleScrollContent")
        matrix = QGridLayout(role_scroll_content)
        matrix.setContentsMargins(0, 0, 4, 0)
        matrix.setColumnStretch(0, 1)
        matrix.setColumnStretch(1, 1)
        matrix.setColumnStretch(2, 0)
        source_heading = QLabel("CURRENT ROLE · V1 SOURCE")
        source_heading.setStyleSheet("color:#8da5b6; font-weight:700;")
        target_heading = QLabel("REPLACE WITH")
        target_heading.setStyleSheet("color:#8da5b6; font-weight:700;")
        swap_heading = QLabel("SWAP")
        swap_heading.setStyleSheet("color:#8da5b6; font-weight:700;")
        matrix.addWidget(source_heading, 0, 0)
        matrix.addWidget(target_heading, 0, 1)
        matrix.addWidget(swap_heading, 0, 2)
        identity_rows: list[tuple[str, str, bool, QComboBox, QCheckBox]] = []
        source_role_widgets: dict[str, tuple[QWidget, QComboBox, QCheckBox]] = {}
        # KEEP V1 is the safe default, but it must not permanently lock a role
        # out of Character Swap.  Remember the most recent real P Picture for
        # each row so manually re-enabling SWAP can restore a valid target.
        last_non_keep_targets: dict[str, str] = {}
        for row_index, (source, baseline_target, is_source_role) in enumerate(identity_sources, 1):
            raw_staged_target = str(
                (staged_by_source.get(source) or {}).get("target_reference") or ""
            ).strip().upper()
            staged_target = (
                KEEP_V1_TARGET
                if raw_staged_target == KEEP_V1_TARGET else
                normalize_picture_reference(raw_staged_target)
            ) or baseline_target
            current_choice = next(
                (
                    choice for choice in self._identity_choices
                    if choice.get("media_id") == baseline_target
                ),
                None,
            )
            source_visual = self._source_role_visuals.get(source, {}) if is_source_role else {}
            current_widget = (
                V1CurrentRoleWidget(source) if is_source_role else QFrame()
            )
            current_widget.setObjectName("shotIdentityCurrentRole")
            current_widget.setStyleSheet(
                "QFrame#shotIdentityCurrentRole { background:#101820; "
                "border:1px solid #294657; border-radius:4px; } "
                "QFrame#shotIdentityCurrentRole[v1Focused=\"true\"] { "
                "border:2px solid #ffe66d; background:#17212a; }"
            )
            current_layout = QHBoxLayout(current_widget)
            current_layout.setContentsMargins(7, 5, 9, 5)
            current_layout.setSpacing(9)
            current_avatar = QLabel()
            current_avatar.setObjectName("shotIdentityCurrentAvatar")
            current_avatar.setFixedSize(52, 52)
            current_avatar.setAlignment(Qt.AlignCenter)
            current_avatar.setStyleSheet(
                "background:#091015; border:1px solid #3b5666; border-radius:3px;"
            )
            has_current_avatar = False
            if is_source_role:
                pixmap = source_visual.get("pixmap", QPixmap())
                if isinstance(pixmap, QPixmap) and not pixmap.isNull():
                    pixmap = pixmap.scaled(
                        QSize(48, 48), Qt.KeepAspectRatioByExpanding,
                        Qt.SmoothTransformation,
                    )
                    current_avatar.setPixmap(pixmap)
                    has_current_avatar = True
                current_avatar.setToolTip(str(source_visual.get("tooltip", "V1 source role")))
            elif current_choice is not None:
                pixmap = current_choice["icon"].pixmap(QSize(48, 48))
                if not pixmap.isNull():
                    current_avatar.setPixmap(pixmap)
                    has_current_avatar = True
            if not has_current_avatar:
                current_avatar.setText(source if is_source_role else f"@{baseline_target}")
            current_text = QLabel(
                (
                    f"{source} · V1 source\nKEEP V1 · no Character Swap"
                    if baseline_target == KEEP_V1_TARGET else
                    f"{source} · V1 source\nreplace with @{baseline_target}"
                )
                if is_source_role else
                (f"@{source}" if baseline_target == source
                 else f"@{source}\ncurrently @{baseline_target}")
            )
            current_text.setWordWrap(True)
            current_text.setStyleSheet("font-weight:700; border:none;")
            if is_source_role:
                current_avatar.setAttribute(Qt.WA_TransparentForMouseEvents, True)
                current_text.setAttribute(Qt.WA_TransparentForMouseEvents, True)
            current_layout.addWidget(current_avatar)
            current_layout.addWidget(current_text, 1)
            matrix.addWidget(current_widget, row_index, 0)
            target_combo = QComboBox()
            target_combo.setObjectName(f"shotRoleTarget_{source}")
            target_combo.setMinimumHeight(62)
            target_combo.setIconSize(QSize(48, 48))
            if is_source_role:
                target_combo.addItem(
                    "KEEP V1 · No Character Swap", KEEP_V1_TARGET
                )
            for choice in self._identity_choices:
                target_combo.addItem(
                    choice["icon"], choice["label"], choice["media_id"]
                )
            if target_combo.findData(staged_target) < 0:
                target_combo.addItem(f"@{staged_target}", staged_target)
            target_combo.setCurrentIndex(max(0, target_combo.findData(staged_target)))
            remembered_target = (
                staged_target if staged_target != KEEP_V1_TARGET else
                baseline_target if baseline_target != KEEP_V1_TARGET else
                next(
                    (
                        str(choice.get("media_id", "")).strip().upper()
                        for choice in self._identity_choices
                        if normalize_picture_reference(choice.get("media_id"))
                    ),
                    "",
                )
            )
            if normalize_picture_reference(remembered_target):
                last_non_keep_targets[source] = remembered_target
            matrix.addWidget(target_combo, row_index, 1)
            swap_checkbox = QCheckBox()
            swap_checkbox.setObjectName(f"shotRoleSwap_{source}")
            swap_checkbox.setChecked(
                not is_source_role
                or (source in selected_roles and staged_target != KEEP_V1_TARGET)
            )
            swap_checkbox.setEnabled(is_source_role)
            swap_checkbox.setToolTip(
                (
                    f"Replace {source} in this Shot. KEEP V1 turns this off automatically; "
                    "checking it again restores the last P Picture."
                ) if is_source_role
                else "Legacy Media Pool identity replacement"
            )
            matrix.addWidget(swap_checkbox, row_index, 2, Qt.AlignCenter)
            if is_source_role:
                target_combo.setEnabled(
                    swap_checkbox.isChecked() or staged_target == KEEP_V1_TARGET
                )
                source_role_widgets[source] = (
                    current_widget, target_combo, swap_checkbox
                )
            identity_rows.append((
                source, baseline_target, is_source_role, target_combo, swap_checkbox
            ))

        def target_choice_changed(role_id: str, target: object) -> None:
            """KEEP V1 defaults SWAP off while preserving a reversible target."""

            role_id = str(role_id or "").strip().upper()
            if role_id not in source_role_widgets:
                return
            _widget, combo, checkbox = source_role_widgets[role_id]
            keep_v1 = str(target or "").strip().upper() == KEEP_V1_TARGET
            checkbox.blockSignals(True)
            checkbox.setChecked(not keep_v1)
            checkbox.blockSignals(False)
            if keep_v1:
                selected_roles.discard(role_id)
            else:
                normalized_target = normalize_picture_reference(target)
                if normalized_target:
                    last_non_keep_targets[role_id] = normalized_target
                selected_roles.add(role_id)
            combo.setEnabled(True)
            if picker is not None:
                picker.set_selected_roles(selected_roles)

        for source_role, (_widget, combo, _checkbox) in source_role_widgets.items():
            combo.currentIndexChanged.connect(
                lambda _index, role=source_role, control=combo:
                target_choice_changed(role, control.currentData())
            )

        def focus_source_role(role_id: str) -> None:
            """Navigate V1 evidence and enable the clicked role's SWAP row."""

            role_id = str(role_id or "").strip().upper()
            if role_id not in source_role_widgets:
                return
            _role_widget, role_combo, role_checkbox = source_role_widgets[role_id]
            keep_v1 = str(role_combo.currentData() or "").upper() == KEEP_V1_TARGET
            if not keep_v1:
                selected_roles.add(role_id)
            role_checkbox.blockSignals(True)
            role_checkbox.setChecked(not keep_v1)
            role_checkbox.blockSignals(False)
            role_combo.setEnabled(True)
            if picker is not None:
                # Raise immediately even if this role has no dedicated evidence
                # frame.  set_frame_content below will retain the same focus
                # when a role-specific frame is available.
                picker.set_focused_role(role_id)
            view = picker_role_views.get(role_id, {})
            if picker is None or not isinstance(view, dict):
                return
            view_pixmap = view.get("pixmap", QPixmap())
            view_roles = deepcopy(view.get("roles") or {})
            if not isinstance(view_pixmap, QPixmap) or view_pixmap.isNull():
                return
            if not isinstance(view_roles, dict):
                view_roles = {}
            for manual_role, manual_bbox in self._source_role_bbox_overrides.items():
                if manual_role not in source_role_widgets:
                    continue
                manual_payload = dict(
                    view_roles.get(manual_role)
                    or picker_roles.get(manual_role)
                    or {}
                )
                manual_payload["bbox_normalized"] = list(manual_bbox)
                manual_payload["position_source"] = "manual_shot_override"
                view_roles[manual_role] = manual_payload
            picker.set_frame_content(
                view_pixmap,
                view_roles,
                focused_role=role_id,
            )
            picker.set_selected_roles(selected_roles)
            if frame_label is not None:
                frame_label.setText(
                    f"V1 frame {int(view.get('frame_index', 0) or 0)} · "
                    f"{float(view.get('time_seconds', 0.0) or 0.0):.3f}s · "
                    f"focused {role_id}" + (
                        "" if (
                            bool(view.get("has_tracked_bbox"))
                            or role_id in self._source_role_bbox_overrides
                        ) else " · no reliable box; Ctrl+click V1 to add one"
                    )
                )
            for source_role, (widget, _combo, _checkbox) in source_role_widgets.items():
                widget.setProperty("v1Focused", source_role == role_id)
                widget.style().unpolish(widget)
                widget.style().polish(widget)
                widget.update()

        def sync_role_controls(role_id: str, additive: bool) -> None:
            role_id = str(role_id).strip().upper()
            if role_id not in source_role_widgets:
                return
            if additive:
                selected_roles.symmetric_difference_update({role_id})
            else:
                selected_roles.clear()
                selected_roles.add(role_id)
            selected_roles.difference_update({
                source_role
                for source_role, (_widget, combo, _checkbox)
                in source_role_widgets.items()
                if str(combo.currentData() or "").upper() == KEEP_V1_TARGET
            })
            for source_role, (_widget, combo, checkbox) in source_role_widgets.items():
                checked = source_role in selected_roles
                checkbox.blockSignals(True)
                checkbox.setChecked(checked)
                checkbox.blockSignals(False)
                combo.setEnabled(
                    checked
                    or str(combo.currentData() or "").upper() == KEEP_V1_TARGET
                )
            if picker is not None:
                picker.set_selected_roles(selected_roles)
            role_widget, role_combo, _checkbox = source_role_widgets[role_id]
            role_scroll.ensureWidgetVisible(role_widget, 12, 24)
            role_combo.setFocus(Qt.MouseFocusReason)

        def checkbox_changed(role_id: str, checked: bool) -> None:
            _widget, combo, checkbox = source_role_widgets[role_id]
            if (
                checked
                and str(combo.currentData() or "").upper() == KEEP_V1_TARGET
            ):
                # A checked KEEP row would be contradictory and would still be
                # skipped by the Relay compiler.  Restore a real P target so
                # the user's explicit click immediately enables a valid pass.
                restored_target = last_non_keep_targets.get(role_id, "")
                restored_index = combo.findData(restored_target)
                if restored_index < 0:
                    restored_index = next(
                        (
                            index for index in range(combo.count())
                            if normalize_picture_reference(combo.itemData(index))
                        ),
                        -1,
                    )
                if restored_index < 0:
                    checkbox.blockSignals(True)
                    checkbox.setChecked(False)
                    checkbox.blockSignals(False)
                    selected_roles.discard(role_id)
                    combo.setEnabled(True)
                    checkbox.setToolTip(
                        f"Load a P Picture before enabling Character Swap for {role_id}."
                    )
                    return
                combo.setCurrentIndex(restored_index)
            if checked:
                selected_roles.add(role_id)
            else:
                selected_roles.discard(role_id)
            combo.setEnabled(checked)
            if picker is not None:
                picker.set_selected_roles(selected_roles)

        def stage_role_bbox(role_id: str, raw_bbox: object) -> None:
            role_id = str(role_id or "").strip().upper()
            if role_id not in source_role_widgets:
                return
            try:
                left, top, right, bottom = [float(value) for value in raw_bbox][:4]
            except (TypeError, ValueError, OverflowError):
                return
            left, top = max(0.0, left), max(0.0, top)
            right, bottom = min(1.0, right), min(1.0, bottom)
            if right - left < 0.02 or bottom - top < 0.02:
                return
            bbox = [
                round(left, 6), round(top, 6),
                round(right, 6), round(bottom, 6),
            ]
            self._source_role_bbox_overrides[role_id] = bbox
            selected_roles.add(role_id)
            _widget, combo, checkbox = source_role_widgets[role_id]
            checkbox.blockSignals(True)
            checkbox.setChecked(True)
            checkbox.blockSignals(False)
            combo.setEnabled(True)
            picker_payload.setdefault("roles", {}).setdefault(role_id, {})[
                "bbox_normalized"
            ] = list(bbox)
            for view_role, view in picker_role_views.items():
                if not isinstance(view, dict):
                    continue
                view_roles = view.setdefault("roles", {})
                payload = dict(view_roles.get(role_id) or {})
                payload["bbox_normalized"] = list(bbox)
                payload["position_source"] = "manual_shot_override"
                view_roles[role_id] = payload
                if view_role == role_id:
                    view["has_tracked_bbox"] = True
            if picker is not None:
                picker.set_selected_roles(selected_roles)
            if frame_label is not None:
                frame_label.setText(
                    frame_label.text().split(" · manual box")[0] + " · manual box saved"
                )

        for source_role, (_widget, _combo, checkbox) in source_role_widgets.items():
            checkbox.toggled.connect(
                lambda checked, role=source_role: checkbox_changed(role, checked)
            )
            if isinstance(_widget, V1CurrentRoleWidget):
                _widget.role_clicked.connect(focus_source_role)
        if picker is not None:
            picker.role_selected.connect(sync_role_controls)
            picker.role_bbox_edited.connect(stage_role_bbox)
        role_scroll.setWidget(role_scroll_content)
        layout.addWidget(role_scroll, 1)

        scope_combo = QComboBox()
        scope_combo.addItem("This Shot only", "shot_only")
        scope_combo.addItem("Linked continuity Shots", "linked_continuity")
        scope_combo.addItem("All appearances of this role", "all_role_appearances")
        scope_combo.setCurrentIndex(0)
        if self._identity_change_payloads:
            staged_scope = str(self._identity_change_payloads[0].get("scope") or "shot_only")
            scope_combo.setCurrentIndex(max(0, scope_combo.findData(staged_scope)))
        scope_form = QFormLayout()
        scope_form.addRow("Identity scope", scope_combo)
        layout.addLayout(scope_form)
        note = QLabel(
            "Linked and All scopes update character references, identity direction, visible speaking "
            "ownership and every affected dirty Segment. They do not invent a new face."
        )
        note.setWordWrap(True)
        note.setObjectName("shotEditorSubtitle")
        layout.addWidget(note)
        buttons = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        buttons.setObjectName("shotIdentityButtons")
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)
        available = dialog.screen().availableGeometry() if dialog.screen() else None
        dialog.resize(
            780,
            min(760, max(520, available.height() - 96)) if available else 700,
        )

        if dialog.exec() != QDialog.Accepted:
            return
        selected_roles = {
            source
            for source, _baseline, is_source_role, _combo, checkbox in identity_rows
            if is_source_role and checkbox.isChecked()
        }
        keep_rows = {
            source
            for source, _baseline, is_source_role, target_combo, _checkbox
            in identity_rows
            if is_source_role
            and str(target_combo.currentData() or "").upper() == KEEP_V1_TARGET
        }
        if source_role_ids and not selected_roles and keep_rows != set(source_role_ids):
            QMessageBox.warning(
                self,
                "Select a V1 person",
                "Select at least one CURRENT ROLE to replace in this Shot.",
            )
            return
        changes: list[dict[str, str]] = []
        for source, baseline_target, is_source_role, target_combo, checkbox in identity_rows:
            raw_target = str(target_combo.currentData() or "").strip().upper()
            keep_v1 = raw_target == KEEP_V1_TARGET
            if is_source_role and not checkbox.isChecked() and not keep_v1:
                continue
            target = (
                KEEP_V1_TARGET if keep_v1 else
                normalize_picture_reference(target_combo.currentData())
            )
            detected_unbound = self._detected_unbound_source_roles.get(source, {})
            if not target or (target == baseline_target and not detected_unbound):
                continue
            direction = next(
                (
                    str(choice.get("direction", ""))
                    for choice in self._identity_choices
                    if choice.get("media_id") == target
                ),
                "",
            )
            change = {
                "source_reference": baseline_target if is_source_role else source,
                "target_reference": target,
                "scope": str(scope_combo.currentData()),
                "target_direction": direction,
            }
            if is_source_role:
                change["source_role_id"] = source
                if detected_unbound:
                    change["detected_unbound"] = True
                    change["detected_scene_index"] = int(
                        detected_unbound.get("scene_index", 0) or 0
                    )
                    change["activate_source_role"] = bool(
                        detected_unbound.get("activate_source_role", False)
                    )
            changes.append(change)
        self._push_history()
        self._identity_change_payloads = changes
        # Empty means the legacy/all-roles behavior. Persist a non-empty list
        # only when this Shot intentionally targets a subset of visible roles.
        self._source_role_swap_selection = (
            [] if set(source_role_ids) == selected_roles
            else [role for role in source_role_ids if role in selected_roles]
        )
        self._refresh_card_values()

    def _edit_camera(self) -> None:
        dialog = QDialog(self)
        dialog.setWindowTitle(f"Camera · {self.cue.cue_id}")
        form = QFormLayout(dialog)
        controls = []
        for label, source in (
            ("Framing", self.framing_combo), ("Angle", self.angle_combo),
            ("Movement", self.movement_combo), ("Speed", self.speed_combo),
            ("Amplitude", self.amplitude_combo),
        ):
            combo = QComboBox()
            combo.setEditable(source.isEditable())
            combo.addItems([source.itemText(index) for index in range(source.count())])
            combo.setCurrentText(source.currentText())
            form.addRow(label, combo)
            controls.append((source, combo))
        buttons = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        form.addRow(buttons)
        if dialog.exec() == QDialog.Accepted:
            self._push_history()
            for source, combo in controls:
                source.setCurrentText(combo.currentText())
            self._refresh_card_values()

    def _edit_text_value(self, title: str, value: str) -> tuple[str, bool]:
        return QInputDialog.getMultiLineText(self, title, title, value)

    def _edit_mouth(self) -> None:
        value, ok = self._edit_text_value("Mouth performance", self.mouth_edit.text())
        if ok:
            self._push_history()
            self.mouth_edit.setText(value.strip())
            self._refresh_card_values()

    def _edit_voice_position(self) -> None:
        labels = [self.voice_position_combo.itemText(i) for i in range(self.voice_position_combo.count())]
        label, ok = QInputDialog.getItem(
            self, "Voice position", "Physical voice origin", labels,
            self.voice_position_combo.currentIndex(), False,
        )
        if ok:
            self._push_history()
            self.voice_position_combo.setCurrentText(label)
            self._refresh_card_values()

    def _edit_lip_sync(self) -> None:
        dialog = QDialog(self)
        dialog.setWindowTitle(f"Lip Sync · {self.cue.cue_id}")
        dialog.setMinimumWidth(620)
        form = QFormLayout(dialog)

        mode_combo = QComboBox()
        for index in range(self.lip_sync_mode_combo.count()):
            mode_combo.addItem(
                self.lip_sync_mode_combo.itemText(index),
                self.lip_sync_mode_combo.itemData(index),
            )
        mode_combo.setCurrentIndex(
            max(0, mode_combo.findData(self.lip_sync_mode_combo.currentData()))
        )

        target_combo = QComboBox()
        target_combo.setIconSize(QSize(42, 42))
        for index in range(self.lip_sync_target_combo.count()):
            target_combo.addItem(
                self.lip_sync_target_combo.itemIcon(index),
                self.lip_sync_target_combo.itemText(index),
                self.lip_sync_target_combo.itemData(index),
            )
        target_combo.setCurrentIndex(
            max(0, target_combo.findData(self.lip_sync_target_combo.currentData()))
        )

        source_combo = QComboBox()
        for index in range(self.lip_sync_source_combo.count()):
            source_combo.addItem(
                self.lip_sync_source_combo.itemText(index),
                self.lip_sync_source_combo.itemData(index),
            )
        source_combo.setCurrentIndex(
            max(0, source_combo.findData(self.lip_sync_source_combo.currentData()))
        )

        def update_enabled() -> None:
            manual = str(mode_combo.currentData()) == "enabled"
            target_combo.setEnabled(manual)
            source_combo.setEnabled(manual)

        mode_combo.currentIndexChanged.connect(update_enabled)
        update_enabled()
        form.addRow("Lip-sync switch", mode_combo)
        form.addRow("Character moving mouth", target_combo)
        form.addRow("Mouth timing source", source_combo)
        note = QLabel(
            "Auto preserves the existing Text Layer or Special Skill assignment. On makes the "
            "selected source the sole mouth-motion clock for the selected character. Off keeps "
            "every visible mouth neutral while authorized off-screen audio may continue. An @A/@V "
            "source must overlap this Shot on the Timeline."
        )
        note.setWordWrap(True)
        note.setObjectName("shotEditorSubtitle")
        form.addRow(note)
        buttons = QDialogButtonBox(QDialogButtonBox.Save | QDialogButtonBox.Cancel)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        form.addRow(buttons)
        if dialog.exec() != QDialog.Accepted:
            return
        self._push_history()
        self.lip_sync_mode_combo.setCurrentIndex(
            max(0, self.lip_sync_mode_combo.findData(mode_combo.currentData()))
        )
        self.lip_sync_target_combo.setCurrentIndex(
            max(0, self.lip_sync_target_combo.findData(target_combo.currentData()))
        )
        self.lip_sync_source_combo.setCurrentIndex(
            max(0, self.lip_sync_source_combo.findData(source_combo.currentData()))
        )
        selected_mode = str(mode_combo.currentData())
        if selected_mode == "enabled":
            self.speech_mode_combo.setCurrentIndex(
                max(0, self.speech_mode_combo.findData("on_screen_speaker"))
            )
        elif selected_mode == "disabled":
            self.speech_mode_combo.setCurrentIndex(
                max(0, self.speech_mode_combo.findData("silent_listener"))
            )
            if not self.mouth_edit.text().strip():
                self.mouth_edit.setText(
                    "lips naturally together; jaw still; blink and breathe only"
                )
        self._refresh_card_values()

    def _edit_action(self) -> None:
        value, ok = self._edit_text_value("Visible action", self.action_edit.toPlainText())
        if ok:
            self._push_history()
            self.action_edit.setPlainText(value.strip())
            self._refresh_card_values()

    def _edit_environment(self) -> None:
        value, ok = self._edit_text_value(
            "Environment", self.environment_edit.toPlainText()
        )
        if ok:
            self._push_history()
            self.environment_edit.setPlainText(value.strip())
            self._refresh_card_values()

